-- Arabic-first semantic service search for Mamnoon.
-- Embeddings are generated by a configured multilingual provider from an Edge Function.
create extension if not exists vector with schema extensions;

create table if not exists public.service_embeddings (
  service_id uuid primary key references public.services(id) on delete cascade,
  content text not null,
  model text not null,
  embedding extensions.vector(384) not null,
  updated_at timestamptz not null default now()
);

alter table public.service_embeddings enable row level security;
revoke all on table public.service_embeddings from anon, authenticated;
grant all on table public.service_embeddings to service_role;

create index if not exists service_embeddings_embedding_hnsw_idx
  on public.service_embeddings
  using hnsw (embedding vector_cosine_ops);

create or replace function public.match_service_embeddings(
  query_embedding extensions.vector(384),
  match_threshold double precision default 0.25,
  match_count integer default 10
)
returns table (
  service_id uuid,
  similarity double precision
)
language sql
stable
security invoker
set search_path = ''
as $$
  select
    se.service_id,
    (1 - (se.embedding <=> query_embedding))::double precision as similarity
  from public.service_embeddings se
  where se.embedding is not null
    and (1 - (se.embedding <=> query_embedding)) >= greatest(-1, least(match_threshold, 1))
  order by se.embedding <=> query_embedding
  limit greatest(1, least(match_count, 30));
$$;

revoke all on function public.match_service_embeddings(extensions.vector, double precision, integer) from public, anon, authenticated;
grant execute on function public.match_service_embeddings(extensions.vector, double precision, integer) to service_role;

comment on table public.service_embeddings is
  'Private multilingual vector index for public service catalog entries; never expose embeddings to client roles.';
